<?php
namespace App\Http\Middleware;use App\Domain\ApiHub\Models\TenantApiUsageEvent;use Closure;use Illuminate\Http\Request;
final class MeterTenantApiV1{public function handle(Request$r,Closure$next){$start=microtime(true);$response=$next($r);if(!$response->headers->has('X-ZIGO-Idempotent-Replay'))TenantApiUsageEvent::firstOrCreate(['request_id'=>$r->attributes->get('zigo_request_id'),'endpoint_code'=>$r->route()?->getName()??$r->path()],['tenant_id'=>$r->attributes->get('tenant')->id,'api_client_id'=>$r->attributes->get('api_client')->id,'api_key_id'=>$r->attributes->get('api_key')->id,'units'=>$response->isSuccessful()?1:0,'http_status'=>$response->getStatusCode(),'duration_ms'=>(int)((microtime(true)-$start)*1000),'occurred_at'=>now(),'created_at'=>now()]);return$response;}}
